$P -c "select _rls_try('$C1', 'update expense_categories set name = ''الإيجار الشهري'' where name = ''ايجار''')" >/dev/null
out=$($P -f "$MIG/0227_expense_categories.sql" 2>&1) || { echo "$out"; echo "   ✗ 0227 ما انعادت بعد التسمية"; fail=1; }
