    "$(fgc "$C1" "select forgive_invoice_debt('${IV}03', 30, 'negotiation', null, 100, 70, 'card')")" "ok"
chk "  المدفوع ٧٠، الإجمالي ٧٠، الخصم ٣٠، المتبقّي صفر، والطريقةُ الغالبة بطاقة" \
    "select amount_paid::int||'|'||total::int||'|'||forgiven::int||'|'||(total-amount_paid)::int||'|'||payment_method from invoices where id='${IV}03'" "70|70|30|0|card"
chk "  ساقٌ واحدة بشكل 0061 حرفاً: {method, amount, at …Z}" \
    "select jsonb_array_length(payment_details)||'|'||(payment_details->0->>'method')||'|'||(payment_details->0->>'amount')::numeric::int||'|'||((payment_details->0->>'at') ~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$')::text||'|'||(select string_agg(k, ',' order by k) from jsonb_object_keys(payment_details->0) k) from invoices where id='${IV}03'" "1|card|70|true|amount,at,method"
chk "  وسطرٌ واحد بالدفتر يحمل الدفعة (٧٠ بطاقة) ولقطةَ ما بعدها (إجمالي ١٠٠، مدفوع ٧٠، متبقٍّ ٣٠)" \
    "select count(*)||'|'||max(pay_amount)::int||'|'||max(pay_method)||'|'||max(total_before)::int||'|'||max(paid_before)::int||'|'||max(due_before)::int from invoice_forgiveness where invoice_id='${IV}03'" "1|70|card|100|70|30"
chk "  receipt_legs يعدّ الدفعةَ (٧٠) لا الخصم" \
    "select coalesce(sum(r.amount), 0)::int::text from (select set_config('request.jwt.claim.sub','$C1',true)) s, receipt_legs() r where r.invoice_id='${IV}03'" "70"
chk "بيعةٌ بلا سِيَق (٤٠ ضمنيّة): التسويةُ تثبّت الضمنيّةَ بتاريخ الفاتورة قبل ساقها" \
    "$(fgc "$C1" "select forgive_invoice_debt('${IV}0e', 30, 'loyal', null, 60, 30, 'cash')")" "ok"
chk "  فالتقاريرُ ترى ٤٠ يوم البيع + ٣٠ اليوم = ٧٠ (لا ٣٠ وحدها)" \
    "select string_agg(r.amount::int::text, ',' order by r.at)||'|'||(min(r.at) = '2026-10-01T09:00:00Z')::text from (select set_config('request.jwt.claim.sub','$C1',true)) s, receipt_legs() r where r.invoice_id='${IV}0e'" "40,30|true"

# ٦) المرتجعُ يستهلك الخصمَ قبل النقد (٤٠+٣٠، دُفع ٣٠، خُصم ٢٠ ⇒ يرجع الـ٣٠: الإجمالي ٣٠، المتبقّي ٠، ولا نقد)
chk "خصمُ ٢٠ على ٤٠+٣٠ مدفوعٌ منها ٣٠" \
    "$(fgc "$C1" "select forgive_invoice_debt('${IV}09', 20, 'loyal', null, 40)")" "ok"
chk "  إرجاعُ سطر الـ٣٠ (الاستقبالُ يرجع — كما بالإنتاج)" \
    "$(fgc "$RCP" "select return_invoice_items('${IV}09', '[{\"item_id\":\"${II}a2\",\"qty\":1}]'::jsonb)")" "ok"
chk "  الإجمالي ٣٠، الخصم ١٠، المدفوع ٣٠، المتبقّي ٠، الربح ٢٠ — ولا ساقَ سالبة (لا نقدَ خرج)" \
    "select total::int||'|'||forgiven::int||'|'||amount_paid::int||'|'||(total-amount_paid)::int||'|'||profit::int||'|'||jsonb_array_length(payment_details) from invoices where id='${IV}09'" "30|10|30|0|20|1"
chk "  وسطرُ استهلاكٍ بالسالب (−١٠، «مرتجع»)" \
    "select string_agg(kind||':'||amount::int||':'||coalesce(note,''), ',' order by created_at, amount desc) from invoice_forgiveness where invoice_id='${IV}09'" "forgive:20:,consumed:-10:مرتجع"
chk "  وإلغاءُ خصمٍ استُهلك منه شيء يُرفض (forgiveness_consumed)" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}09' and kind='forgive'), 'غلط بالمبلغ')")" "forgiveness_consumed"

# ٧) التعديلُ يبقي الخصمَ ما دام الدينُ يحمله، ويستهلكه حين لا
chk "خصمُ ٣٠ على ١٠٠ مدفوعٌ منها ٢٠" \
    "$(fgc "$C1" "select forgive_invoice_debt('${IV}0a', 30, 'hardship', null, 80)")" "ok"
chk "  المديرُ يضيف سطر ١٠: الخام ١١٠ ⇒ الخصمُ يبقى ٣٠ والإجمالي ٨٠" \
    "$(fgc "$C1" "select edit_invoice_lines('${IV}0a', '[{\"name\":\"مية\",\"qty\":1,\"unit_price\":100,\"unit_cost\":40},{\"name\":\"عشرة\",\"qty\":1,\"unit_price\":10,\"unit_cost\":5}]'::jsonb)")" "ok"
chk "    (إجمالي ٨٠، خصم ٣٠، ربح ٣٥، متبقٍّ ٦٠، ولا سطرَ استهلاك)" \
    "select total::int||'|'||forgiven::int||'|'||profit::int||'|'||(total-amount_paid)::int||'|'||(select count(*) from invoice_forgiveness where invoice_id='${IV}0a') from invoices where id='${IV}0a'" "80|30|35|60|1"
chk "  وينزل لسطر ٤٠ وحده: الخام ٤٠ والمدفوع ٢٠ ⇒ الخصمُ ٢٠ والإجمالي ٢٠" \
    "$(fgc "$C1" "select edit_invoice_lines('${IV}0a', '[{\"name\":\"أربعون\",\"qty\":1,\"unit_price\":40,\"unit_cost\":10}]'::jsonb)")" "ok"
chk "    (إجمالي ٢٠، خصم ٢٠، متبقٍّ ٠، واستهلاكُ −١٠ «تعديل»)" \
    "select total::int||'|'||forgiven::int||'|'||(total-amount_paid)::int||'|'||(select string_agg(amount::int||':'||coalesce(note,''), ',') from invoice_forgiveness where invoice_id='${IV}0a' and kind='consumed') from invoices where id='${IV}0a'" "20|20|0|-10:تعديل"

# ٨) الإلغاء: يرجع الدينُ كما كان، والسطرُ يبقى مشطوباً
chk "خصمُ ٤٠ على ١٠٠ (ربح ٥٠)" \
    "$(fgc "$C1" "select forgive_invoice_debt('${IV}0b', 40, 'loyal')")" "ok"
$P -c "delete from staff_elevations where user_id = '$RCP';" >/dev/null
chk "  الاستقبالُ بلا مفتاح لا يلغي" \
    "$(fgc "$RCP" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}0b'), 'غلط بالمبلغ')")" "not_allowed"
chk "  والإلغاءُ بلا سبب: reason_required" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}0b'), '  ')")" "reason_required"
chk "  وسطرُ الاستهلاك لا يُلغى وحده (entry_not_voidable)" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}09' and kind='consumed'), 'غلط بالمبلغ')")" "entry_not_voidable"
chk "  المديرُ يلغي بسبب" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}0b'), 'غلط بالمبلغ')")" "ok"
chk "  الإجمالي ١٠٠ والربح ٥٠ والخصم ٠، والسطرُ باقٍ مختوماً بسببه ومن ألغاه" \
    "select i.total::int||'|'||i.profit::int||'|'||i.forgiven::int||'|'||(f.voided_at is not null)::text||'|'||f.void_reason||'|'||(f.voided_by='$C1')::text from invoices i join invoice_forgiveness f on f.invoice_id=i.id where i.id='${IV}0b'" "100|50|0|true|غلطبالمبلغ|true"
chk "  ومرّةً ثانية: already_voided" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}0b'), 'غلط بالمبلغ')")" "already_voided"
# خصمُ ٤٠ (الإجمالي ٦٠)، ثم طلبُ توصيلٍ بوصلٍ ٦٠ — الإلغاءُ يرفع الإجماليَّ ١٠٠ والسائقُ مطلوبٌ منه ٦٠.
chk "خصمُ ٤٠ ثم طلبُ توصيلٍ بالطريق بوصل ٦٠" \
    "$(fgc "$C1" "select forgive_invoice_debt('${IV}11', 40, 'loyal', null, 100)")" "ok"
$P -c "insert into delivery_orders (id, clinic_id, invoice_id, status, cod_amount) values ('${II}d1', '$C1', '${IV}11', 'out', 60) on conflict (id) do nothing;" >/dev/null
chk "  الإلغاءُ وطلبُ التوصيل مفتوح: invoice_has_open_delivery" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}11'), 'غلط بالمبلغ')")" "invoice_has_open_delivery"
chk "    (الإجمالي ٦٠ والخصم ٤٠ ووصلُ السائق ٦٠ — لا شيءَ تحرّك)" \
    "select i.total::int||'|'||i.forgiven::int||'|'||d.cod_amount::int from invoices i join delivery_orders d on d.invoice_id = i.id where i.id='${IV}11'" "60|40|60"
$P -c "update delivery_orders set status = 'delivered', delivered_at = now(), collected_at = now() where id = '${II}d1';" >/dev/null
chk "  وبعد التحصيل (الزبونُ هو المدين): يمرّ" \
    "$(fgc "$C1" "select void_invoice_forgiveness((select id from invoice_forgiveness where invoice_id='${IV}11'), 'غلط بالمبلغ')")" "ok"

# ٩) النسبة: صاحبُ العيادة وحده يغيّرها، والسقفُ يتبعها
$P -c "insert into staff_elevations(user_id, clinic_id, until) values ('$RCP','$C1', now() + interval '30 minutes')
       on conflict (user_id) do update set until = excluded.until;" >/dev/null
chk "الاستقبالُ بمفتاح المدير لا يغيّر النسبة (forgive_pct_owner_only)" \
    "$(fgc "$RCP" "update clinic_prefs set forgive_profit_pct = 50 where clinic_id = '$C1'")" "forgive_pct_owner_only"
chk "  ولا يدرج صفّاً بنسبةٍ غير الافتراضيّة" \
    "$(fgc "$RCP" "insert into clinic_prefs (clinic_id, forgive_profit_pct) values ('$C1', 50) on conflict (clinic_id) do nothing")" "forgive_pct_owner_only"
$P -c "update _dvtest_flags set admin = true; insert into platform_sessions(admin_id, acting_clinic) values ('$ADM','$C1') on conflict do nothing;" >/dev/null
chk "  مشغّلُ المنصّة داخل العيادة يرى صفَّها (فالرفضُ التالي من المحفّز لا من RLS)" \
    "select _fgv('$ADM', \$q\$select forgive_profit_pct::text from clinic_prefs where clinic_id = '$C1'\$q\$)" "100"
chk "  ولا يغيّر النسبة — auth_role_base() مديرٌ له بلا صفِّ مفتاح (forgive_pct_owner_only)" \
    "$(fgc "$ADM" "update clinic_prefs set forgive_profit_pct = 50 where clinic_id = '$C1'")" "forgive_pct_owner_only"
$P -c "update _dvtest_flags set admin = false; delete from platform_sessions;" >/dev/null
chk "  وصاحبُ العيادة يغيّرها" \
    "select _rls_try('$C1', 'update clinic_prefs set forgive_profit_pct = 50 where clinic_id = ''$C1''')" "rows:1"
chk "  وخارج ٠–١٠٠ يُرفض (23514)" \
    "select left(_rls_try('$C1', 'update clinic_prefs set forgive_profit_pct = 150 where clinic_id = ''$C1'''), 13)" "guarded:23514"
chk "  ونسبة ٥٠ ⇒ المسموح ٣٧.٥ من ربح ٧٥: ٤٠ بالمفتاح فوق السقف" \
    "$(fgc "$RCP" "select forgive_invoice_debt('${IV}0d', 40, 'loyal')")" "above_profit_needs_owner"
chk "  و٣٧.٥ تمرّ" \
    "$(fgc "$RCP" "select forgive_invoice_debt('${IV}0d', 37.5, 'loyal')")" "ok"
chk "    والسطرُ يحفظ النسبة" \
    "select pct||':'||amount from invoice_forgiveness where invoice_id='${IV}0d'" "50:37.50"
$P -c "update clinic_prefs set forgive_profit_pct = 100 where clinic_id = '$C1';" >/dev/null

# ١٠) سِيَقُ الدفع: الموظّفُ يغيّر الطريقةَ وحدها، والمبالغُ للمدير
$P -c "delete from staff_elevations where user_id = '$RCP';" >/dev/null
chk "الاستقبالُ يغيّر طريقةَ الساق الوحيدة (setInvoicePaymentMethod)" \
    "select _rls_try('$RCP', 'update invoices set payment_method = ''card'', payment_details = jsonb_set(payment_details, ''{0,method}'', ''\"card\"'') where id = ''${IV}0c''')" "rows:1"
chk "  ولا مبلغَها (payment_legs_frozen)" \
    "$(fgc "$RCP" "update invoices set payment_details = jsonb_set(payment_details, '{0,amount}', '60') where id = '${IV}0c'")" "payment_legs_frozen"
chk "  ولا وقتَها" \
    "$(fgc "$RCP" "update invoices set payment_details = jsonb_set(payment_details, '{0,at}', '\"2026-01-01T00:00:00.000Z\"') where id = '${IV}0c'")" "payment_legs_frozen"
chk "  ولا يضيف ساقاً" \
    "$(fgc "$RCP" "update invoices set payment_details = payment_details || '[{\"method\":\"cash\",\"amount\":1}]'::jsonb where id = '${IV}0c'")" "payment_legs_frozen"
chk "  والمديرُ يقسّم" \
    "select _rls_try('$C1', 'update invoices set payment_details = ''[{\"method\":\"cash\",\"amount\":60,\"at\":\"2026-10-01T09:00:00.000Z\"},{\"method\":\"card\",\"amount\":40,\"at\":\"2026-10-01T09:00:00.000Z\"}]'' where id = ''${IV}0c''')" "rows:1"
# فاتورةٌ بثلاث سِيَق، بينها مرتجعٌ سالبٌ بملاحظته (الفاتورة و): ما يكتبه محرّرُ «دفع مجزأ»
# (setInvoicePaymentDetails: يبني {method, amount, at} ويرمي الملاحظة ويؤخّر السالب) مرفوضٌ للموظّف
# ولو غيّر الطريقةَ وحدها — فالواجهةُ تُخفي المحرّرَ عنه (canEditLegs، manager-mode-test).
chk "سِيَقٌ ثلاث بسالبٍ موسوم: الاستقبالُ يغيّر طريقةَ الساق الثالثة بمكانها" \
    "select _rls_try('$RCP', 'update invoices set payment_details = jsonb_set(payment_details, ''{2,method}'', ''\"card\"'') where id = ''${IV}0f''')" "rows:1"
chk "  والملاحظةُ والسالبُ بمكانهما" \
    "select (payment_details->1->>'note')||'|'||(payment_details->1->>'amount')::int||'|'||(payment_details->2->>'method') from invoices where id='${IV}0f'" "مرتجع:علبة|-30|card"
chk "  وما يرسله محرّرُ «دفع مجزأ» (السالبُ آخراً، والملاحظةُ لا) مرفوضٌ له (payment_legs_frozen)" \
    "$(fgc "$RCP" "update invoices set payment_details = jsonb_build_array(payment_details->0, payment_details->2, payment_details->1) where id = '${IV}0f'")" "payment_legs_frozen"
chk "  ونفسُه للمدير يمرّ" \
    "select _rls_try('$C1', 'update invoices set payment_details = jsonb_build_array(payment_details->0, payment_details->2, payment_details->1) where id = ''${IV}0f''')" "rows:1"
chk "  والتسديدُ من «تحصيل» (settle_invoice) يبقى للاستقبال" \
    "select _rls_try('$RCP', 'select settle_invoice(''${IV}02'', 10, ''cash'')')" "rows:1"
chk "    (دُفع ١٠ من ١٠٠)" "select amount_paid::int::text from invoices where id='${IV}02'" "10"

# ١١) forgiven والدفترُ لا يُكتبان مباشرةً
chk "الاستقبالُ لا يكتب forgiven مباشرةً (invoice_forgiven_frozen)" \
    "$(fgc "$RCP" "update invoices set forgiven = 0 where id = '${IV}01'")" "invoice_forgiven_frozen"
chk "  ولا المديرُ (الثابتُ لا ينكسر من PATCH)" \
    "$(fgc "$C1" "update invoices set forgiven = 0 where id = '${IV}01'")" "invoice_forgiven_frozen"
chk "  ولا فاتورةٌ تُدرج بخصمٍ جاهز" \
    "$(fgc "$C1" "insert into invoices (id, clinic_id, total, forgiven) values ('${IV}ff', '$C1', 10, 5)")" "invoice_forgiven_frozen"
chk "الدفترُ لا يُدرج فيه مباشرةً (42501)" \
    "select left(_rls_try('$C1', 'insert into invoice_forgiveness (clinic_id, invoice_id, kind, amount, reason_code) values (''$C1'', ''${IV}01'', ''forgive'', 1, ''loyal'')'), 13)" "guarded:42501"
chk "  ولا يُعدَّل" \
    "select left(_rls_try('$C1', 'update invoice_forgiveness set amount = 1'), 13)" "guarded:42501"
chk "  ولا يُحذف" \
    "select left(_rls_try('$C1', 'delete from invoice_forgiveness'), 13)" "guarded:42501"
chk "  والدالّةُ الداخليّة لا تُنادى" \
    "select left(_rls_try('$C1', 'select invoice_forgiveness_consume(''$C1'', ''${IV}01'', 1, ''x'', 1, 1)'), 13)" "guarded:42501"

# ١٢) الثابت والقراءة
chk "الثابت: forgiven = Σ السطور غير الملغاة، لكلّ فاتورة" \
    "select count(*)::text from invoices i where i.id::text like 'dddddddd-0241-%' and i.forgiven <> coalesce((select sum(f.amount) from invoice_forgiveness f where f.invoice_id = i.id and f.voided_at is null), 0)" "0"
chk "  وكلُّ فاتورةٍ خُصم عليها بقي إجماليُّها = (المجموع − الخصم) − forgiven" \
    "select count(*)::text from invoices i where i.id::text like 'dddddddd-0241-%' and i.status <> 'refunded' and exists (select 1 from invoice_forgiveness f where f.invoice_id = i.id) and i.total <> greatest(i.subtotal - i.discount, 0) - i.forgiven" "0"
chk "list_invoice_forgiveness: الاستقبالُ يرى سطرَي الفاتورة ١، والعيادةُ الأخرى لا شيء" \
    "select _fgv('$RCP', \$q\$select count(*)::text from list_invoice_forgiveness(array['${IV}01'::uuid])\$q\$)||'|'||_fgv('$C2', \$q\$select count(*)::text from list_invoice_forgiveness(array['${IV}01'::uuid])\$q\$)" "2|0"
chk "  والملغى معها (الفاتورة ب: سطرٌ مختوم)" \
    "select _fgv('$RCP', \$q\$select string_agg((voided_at is not null)::text, ',') from list_invoice_forgiveness(array['${IV}0b'::uuid])\$q\$)" "true"
chk "report_forgiveness: كلُّ سطور العيادة بالمدّة، باسم الزبون" \
    "select (_fgv('$C1', \$q\$select count(*)::text||':'||count(*) filter (where r.customer_name = 'أبو حسن') from report_forgiveness(now() - interval '1 hour', now() + interval '1 hour') r where r.invoice_id::text like 'dddddddd-0241-%'\$q\$) = (select count(*)::text||':2' from invoice_forgiveness where invoice_id::text like 'dddddddd-0241-%'))::text" "true"
chk "  والعيادةُ الأخرى لا شيء" \
    "select _fgv('$C2', \$q\$select count(*)::text from report_forgiveness(now() - interval '1 hour', now() + interval '1 hour')\$q\$)" "0"
chk "  وبلا مدّة: خطأٌ لا قائمةٌ فارغة (range_required)" \
    "$(fgc "$C1" "select * from report_forgiveness(null, now())")" "range_required"
chk "invoice_settlements: الخصمُ الحيّ منذ ساعة يُرى (الفاتورة ١)، والملغى وحده لا (الفاتورة ب)" \
    "select _fgv('$RCP', \$q\$select (bool_or(s.id = '${IV}01') and not bool_or(s.id = '${IV}0b'))::text from invoice_settlements(null, 'all', now() - interval '1 hour') s\$q\$)" "true"
# «تسديد دفعة» لدين الزبون وحده (قرارُ المالك): ساقُ تحصيل التوصيل — طلبٌ غيرُ مُرجَع و(collected_at فارغ أو
# at ≤ collected_at + ١٠ دقائق) — لا تجيب فاتورتَها. ٢٠: السائقُ ختم collected_at بساعة جهازه والساقُ بعده بـ٤ ثوانٍ؛
# ٢١: التحصيلُ ثم دفعةُ الزبون بالعيادة بعد ساعتين؛ ٢٢: طلبٌ مُرجَع؛ ٢٣: شركةٌ لم يُختم تحصيلُها (سدادٌ جزئيّ).
$P -c "insert into invoices (id, clinic_id, customer_name, subtotal, total, cost_total, profit, amount_paid, status, created_at, payment_details) values
         ('${IV}20', '$C1', 'وصل سائق',  100, 100, 50, 50, 100, 'paid', '2026-10-02T09:00:00Z', '[{\"method\":\"cash\",\"amount\":100,\"at\":\"2026-10-02T10:00:04.000Z\"}]'),
         ('${IV}21', '$C1', 'باقي بالعيادة', 100, 100, 50, 50, 100, 'paid', '2026-10-02T09:00:00Z', '[{\"method\":\"cash\",\"amount\":60,\"at\":\"2026-10-02T10:00:03.000Z\"},{\"method\":\"card\",\"amount\":40,\"at\":\"2026-10-02T12:00:00.000Z\"}]'),
         ('${IV}22', '$C1', 'رجع الطلب', 100, 100, 50, 50, 100, 'paid', '2026-10-02T09:00:00Z', '[{\"method\":\"cash\",\"amount\":100,\"at\":\"2026-10-03T10:00:00.000Z\"}]'),
         ('${IV}23', '$C1', 'شركة جزئي', 100, 100, 50, 50, 60,  'paid', '2026-10-02T09:00:00Z', '[{\"method\":\"cash\",\"amount\":60,\"at\":\"2026-10-04T10:00:00.000Z\"}]')
       on conflict (id) do nothing;
       insert into delivery_orders (id, clinic_id, invoice_id, status, cod_amount, delivered_at, collected_at, returned_at) values
         ('${II}e0', '$C1', '${IV}20', 'delivered', 100, '2026-10-02T09:55:00Z', '2026-10-02T10:00:00Z', null),
         ('${II}e1', '$C1', '${IV}21', 'delivered', 100, '2026-10-02T09:55:00Z', '2026-10-02T10:00:00Z', null),
         ('${II}e2', '$C1', '${IV}22', 'returned',  100, null,                   null,                   '2026-10-02T11:00:00Z'),
         ('${II}e3', '$C1', '${IV}23', 'delivered', 100, '2026-10-03T09:00:00Z', null,                   null)
       on conflict (id) do nothing;" >/dev/null
# «on conflict do nothing» يبلع تصادمَ معرّف بصمت (كان طلبُ ٢١ بمعرّف d1، وهو طلبُ الفاتورة ١١ قائماً، فبقيت ٢١ بلا طلبٍ ومرّ حكمُها صدفةً) — فالقالبُ يُعدّ قبل أيّ حكم.
chk "  (القالب: لكلّ فاتورةٍ من ٢٠–٢٣ طلبُها بحالته وختمه)" \
    "select string_agg(right(invoice_id::text, 2)||':'||status||':'||(collected_at is null)::text, ',' order by invoice_id) from delivery_orders where invoice_id in ('${IV}20','${IV}21','${IV}22','${IV}23')" \
    "20:delivered:false,21:delivered:false,22:returned:true,23:delivered:true"
chk "invoice_settlements: تحصيلُ التوصيل وحده لا يجيب فاتورتَه (٢٠، ٢٣)، ودفعةُ الزبون بعده تجيبها (٢١)، والمُرجَعُ لا يُخفي (٢٢)" \
    "select _fgv('$RCP', \$q\$select coalesce(string_agg(right(s.id::text, 2), ',' order by s.id), '-') from invoice_settlements(null, 'all', '2026-09-01T00:00:00Z') s where s.id in ('${IV}20','${IV}21','${IV}22','${IV}23')\$q\$)" "21,22"
chk "  ومنذ ما بعد التحصيل: ٢١ بدفعة الزبون وحدها" \
    "select _fgv('$RCP', \$q\$select coalesce(string_agg(right(s.id::text, 2), ',' order by s.id), '-') from invoice_settlements(null, 'all', '2026-10-02T11:00:00Z') s where s.id in ('${IV}20','${IV}21')\$q\$)" "21"
chk "invoice_delivery_marks: طلبٌ غيرُ مُرجَع ومتى حُصِّل (٢٢ المُرجَع بلا علامة)" \
    "select _fgv('$RCP', \$q\$select string_agg(right(invoice_id::text, 2)||':'||(collected_at is null)::text, ',' order by invoice_id) from invoice_delivery_marks(array['${IV}20','${IV}21','${IV}22','${IV}23','${IV}01']::uuid[])\$q\$)" "20:false,21:false,23:true"
chk "  وعيادةٌ أخرى والمصوّر لا يريان شيئاً" \
    "select _fgv('$C2', \$q\$select count(*)::text from invoice_delivery_marks(array['${IV}20','${IV}23']::uuid[])\$q\$)||'|'||_fgv('$PHO', \$q\$select count(*)::text from invoice_delivery_marks(array['${IV}20','${IV}23']::uuid[])\$q\$)" "0|0"
chk "  وبلا معرّفات: لا شيء (لا كلُّ العيادة)" \
    "select _fgv('$RCP', \$q\$select count(*)::text from invoice_delivery_marks(null)\$q\$)" "0"
chk "  invoker بمسارٍ مثبَّت، وممنوعةٌ على anon، ومسموحةٌ للمسجَّل" \
    "select (not prosecdef)::text||':'||(coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text||':'||has_function_privilege('anon', oid, 'execute')::text||':'||has_function_privilege('authenticated', oid, 'execute')::text from pg_proc where proname='invoice_delivery_marks'" "true:true:false:true"
chk "  وinvoice_settlements تقرأ القاعدةَ نفسَها (المُرجَع + المهلة)" \
    "select (prosrc like '%d.status <> ''returned''%' and prosrc like '%d.collected_at is null or safe_ts(l->>''at'') <= d.collected_at + interval ''10 minutes''%')::text from pg_proc where proname='invoice_settlements'" "true"
chk "عزل: العيادةُ الأخرى لا ترى الدفتر، ولا المصوّر" \
    "select _rls_try('$C2', 'select 1 from invoice_forgiveness')||'|'||_rls_try('$PHO', 'select 1 from invoice_forgiveness')" "rows:0|rows:0"
chk "التدقيق: الخصمُ debt_forgive والإلغاءُ debt_forgive_void" \
    "select string_agg(distinct audit_kind(entity, action, details), ',' order by audit_kind(entity, action, details)) from audit_log where entity = 'invoice_forgiveness' and clinic_id = '$C1' and coalesce(details->>'kind', '') <> 'consumed'" "debt_forgive,debt_forgive_void"
chk "  وسطرُ الاستهلاك (كتبه مرتجعُ الاستقبال) تعديلُ فاتورة لا «خصم على الدين»" \
    "select string_agg(distinct audit_kind(entity, action, details), ',')||'|'||count(*) filter (where actor = '$RCP')::text from audit_log where entity = 'invoice_forgiveness' and clinic_id = '$C1' and details->>'kind' = 'consumed'" "sale_edit|1"

# ١٣) الثوابتُ الساكنة
chk "الخصمُ والإلغاء: definer بمسارٍ مثبَّت، ويقرآن الفاتورةَ بعيادة الجلسة نصّاً، ويقفلان الصفّ" \
    "select string_agg(proname||':'||prosecdef::text||':'||(coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text||':'||(prosrc like '%clinic_id = v_clinic%' and prosrc like '%for update%')::text, ',' order by proname) from pg_proc where proname in ('forgive_invoice_debt','void_invoice_forgiveness')" \
    "forgive_invoice_debt:true:true:true,void_invoice_forgiveness:true:true:true"
chk "  والكتّابُ الأربعة يقفلون الفاتورة (settle_invoice، تصحيحُ التحصيل، تعديلُ البنود، المرتجع)" \
    "select string_agg(proname||':'||(prosrc ~ 'from invoices where id = p_invoice and clinic_id = v_clinic for update')::text, ',' order by proname) from pg_proc where proname in ('settle_invoice','correct_invoice_receipt','edit_invoice_lines_unguarded','return_invoice_items')" \
    "correct_invoice_receipt:true,edit_invoice_lines_unguarded:true,return_invoice_items:true,settle_invoice:true"
chk "  وكلُّ دالّةٍ تكتب amount_paid أو payment_details على invoices تقفل صفَّها (لا كاتبَ خامساً بلا قفل)" \
    "select count(*)::text||':'||coalesce(string_agg(p.proname, ',' order by p.proname), '') from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prolang = (select oid from pg_language where lanname = 'plpgsql') and p.prosrc ~* 'update\s+invoices\s+set[^;]*(amount_paid|payment_details)' and p.prosrc !~* 'from\s+invoices\s+where[^;]*for\s+update' and p.proname not like '\_%'" "0:"
chk "تصحيحُ التحصيل بعد إعادة تعريفه: ١٠٠ مدفوعة، ٢٠ ما وصلت ⇒ المدفوع ٨٠ وساقٌ سالبة بسببها" \
    "$(fgc "$C1" "select correct_invoice_receipt('${IV}10', 20, 'ما وصل كامل')")" "ok"
chk "  (المدفوع ٨٠، سِيَقٌ ٢، والسالبةُ −٢٠ بملاحظتها)" \
    "select amount_paid::int||'|'||jsonb_array_length(payment_details)||'|'||(payment_details->1->>'amount')::numeric::int||'|'||(payment_details->1->>'note') from invoices where id='${IV}10'" "80|2|-20|ماوصلكامل"
chk "  والمحفّزاتُ والقراءةُ والاستهلاك invoker بمسارٍ مثبَّت" \
    "select count(*)::text from pg_proc where proname in ('invoices_guard_forgiven','invoices_guard_legs','clinic_prefs_guard_forgive_pct','list_invoice_forgiveness','report_forgiveness','invoice_settlements','invoice_forgiveness_consume') and not prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%'" "7"
chk "  ولا شيءَ لـanon" \
    "select count(*)::text from pg_proc p where p.proname in ('forgive_invoice_debt','void_invoice_forgiveness','list_invoice_forgiveness','report_forgiveness','pin_elevation_live','invoice_forgiveness_consume') and has_function_privilege('anon', p.oid, 'execute')" "0"
chk "  والداخليّتان لا تُنادَيان من المسجَّل" \
    "select count(*)::text from pg_proc p where p.proname in ('invoice_forgiveness_consume','edit_invoice_lines_unguarded') and has_function_privilege('authenticated', p.oid, 'execute')" "0"
chk "  والدفترُ: قراءةٌ وحدها للمسجَّل، ولا شيءَ لـanon" \
    "select has_table_privilege('authenticated','public.invoice_forgiveness','select')::text||'|'||has_table_privilege('authenticated','public.invoice_forgiveness','insert')::text||'|'||has_table_privilege('anon','public.invoice_forgiveness','select')::text" "true|false|false"
chk "السياجُ يغطّي الدفتر، ولا سياسةَ تقرأ جدولَها" \
    "select coalesce(string_agg(t, ','), '')||'|'||(select count(*) from verify_no_self_ref_policies())::text from verify_photographer_fence() t where t like 'invoice_forgiveness%'" "|0"
chk "والكنسُ ومعاينتُه ونبضُه يعدّون الدفترَ مالاً (سنة)" \
    "select count(*)::text from pg_proc where proname in ('purge_audit_log','audit_log_preview','system_health') and prosrc like '%invoice_forgiveness%'" "3"
# حالةُ الإنتاج (مقيسةٌ ١٦/١٠ بالبصمة): غلافُ 0113 لم ينزل، وedit_invoice_lines هو جسمُ البنود نفسُه بلا
# _unguarded. نعيد الحالةَ ذاتها هنا ثم 0241: لو أنشأت _unguarded وحدها لبقي الإنتاجُ ينادي الجسمَ القديم.
$P -c "drop function edit_invoice_lines(uuid, jsonb, text);
       alter function edit_invoice_lines_unguarded(uuid, jsonb, text) rename to edit_invoice_lines;
       grant execute on function edit_invoice_lines(uuid, jsonb, text) to authenticated;" >/dev/null
chk "  (الحالةُ المقيسة: لا _unguarded، والاسمُ العامّ هو الجسمُ بلا حارس دور)" \
    "select (to_regprocedure('edit_invoice_lines_unguarded(uuid, jsonb, text)') is null)::text||'|'||(select (prosrc not like '%auth_role()%')::text from pg_proc where proname='edit_invoice_lines')" "true|true"
out=$($P -f "$MIG/0241_debt_forgiveness.sql" 2>&1) || { echo "$out"; echo "   ✗ 0241 ما انعادت على حالة الإنتاج"; fail=1; }
chk "حالةُ الإنتاج بلا غلاف 0113: 0241 تعيد التسمية وتنشئ الغلاف، والجسمُ الداخليّ يستهلك الخصم ولا منحَ له" \
    "select (to_regprocedure('edit_invoice_lines_unguarded(uuid, jsonb, text)') is not null)::text
            ||'|'||(select (prosrc like '%auth_role()%' and prosrc like '%edit_invoice_lines_unguarded%')::text from pg_proc where proname='edit_invoice_lines')
            ||'|'||(select (prosrc like '%invoice_forgiveness_consume%')::text from pg_proc where proname='edit_invoice_lines_unguarded')
            ||'|'||(select has_function_privilege('authenticated', 'edit_invoice_lines_unguarded(uuid, jsonb, text)', 'execute')::text)
            ||'|'||(select has_function_privilege('authenticated', 'edit_invoice_lines(uuid, jsonb, text)', 'execute')::text)" "true|true|true|false|true"
$P -c "delete from staff_elevations;" >/dev/null
chk "  والاستقبالُ يُرفض بالغلاف نفسِه (المديرُ وحده — حارسُ 0113 الذي ظُنّ نازلاً)" \
    "select regexp_replace(_rls_try('$RCP', format('select edit_invoice_lines(%L::uuid, %L::jsonb, null)', '${IV}10', '[]')), '^guarded:[^:]*:', '')" "notallowed"
$P -c "delete from staff_elevations; delete from memberships where user_id = '$MGR';
       delete from delivery_orders where invoice_id::text like 'dddddddd-0241-%';
       delete from invoice_items where invoice_id::text like 'dddddddd-0241-%';
       delete from invoices where id::text like 'dddddddd-0241-%';" >/dev/null

# ── 0242: «تاريخ المبيع» — فاتورةٌ نُسيت تُسجَّل بيومها ─────────────────────────
echo "▸ 0242: فاتورةٌ نُسيت تُسجَّل بيومها — بشرطها، وبلا بابٍ جانبيّ"
BD=b2420000-0000-4000-8000-0000000000
# الحزمةُ تعيد تنزيلَ هجراتٍ أقدم بأقسامها (0226 بقسم الأسعار، و0241 مرّتين بقسمها) فترجع audit_change
# وaudit_kind لنسختيهما — وبالإنتاج 0242 آخرُ من يعرّف audit_change، و0261 آخرُ من يعرّف audit_kind (نصُّ 0242 حرفاً
# وسطرُ الراجيتة — فالفحصُ أدناه يقرأ 0261 ويجد sale_backdated فيه). أوّلُ تشغيلٍ بـCI قاسها: سطرُ التدقيق بلا sold_at
# فرجع الفحصُ فارغاً. فالشرطُ نفسُه يُقاس أوّلاً **على الملفّات** (آخرُ تعريفٍ بالهجرات هو ما يعيش بالإنتاج — نسخةٌ
# لاحقةٌ من نصٍّ أقدم كانت ستُسقط الفرعين بصمت)، ثم تُعاد 0242 هنا كما يعيد قسمُ 0241 هجرتَه.
LAST_AC=$(grep -lE "create or replace function (public\.)?audit_change\(" "$MIG"/*.sql | sort | tail -1)
LAST_AK=$(grep -lE "create or replace function (public\.)?audit_kind\(" "$MIG"/*.sql | sort | tail -1)
chk "آخرُ تعريفٍ لـaudit_change بالهجرات يحفظ ختمَ الإدخال ويومَ البيع ($(basename "$LAST_AC"))" \
    "select '$(grep -q "'recorded_at'" "$LAST_AC" && grep -q "sold_at" "$LAST_AC" && echo true || echo false)'" "true"
chk "  وآخرُ تعريفٍ لـaudit_kind يسمّي sale_backdated ($(basename "$LAST_AK"))" \
    "select '$(grep -q "sale_backdated" "$LAST_AK" && echo true || echo false)'" "true"
out=$($P -f "$MIG/0242_backdated_sale.sql" 2>&1) || { echo "$out"; echo "   ✗ 0242 ما انعادت"; fail=1; }
# محفّزُ التدقيق على الفواتير بشكل الإنتاج (audit_all) — القالبُ كان بلاه، والتسميةُ تُقرأ منه.
$P -c "delete from staff_elevations; update _dvtest_flags set admin = false; delete from platform_sessions;
       drop trigger if exists audit_all on invoices;
       create trigger audit_all after insert or update or delete on invoices for each row execute function audit_change();
       drop trigger if exists audit_all on products;
       create trigger audit_all after insert or update or delete on products for each row execute function audit_change();
       insert into products(id, clinic_id, name, barcode, stock, purchase_price, sell_price) values
         ('${BD}01','$C1','بيعة أمس','242001', 10, 500, 1000) on conflict do nothing;" >/dev/null
CART242="jsonb_build_array(jsonb_build_object('product_id','${BD}01','name','بيعة أمس','qty',2,'unit_price',1000,'unit_cost',500,'stock_qty',2))"
# لحظةٌ بيومٍ محلّيّ (بغداد): «قبل N يوم الساعة ١٥:٠٠».
dayAt() { echo "((((now() at time zone 'Asia/Baghdad')::date - $1) + time '15:00') at time zone 'Asia/Baghdad')"; }
# نداءُ البيعة يرجع معرّفَ الفاتورة: co <مرجع> <تعبيرُ اللحظة أو null> [توقيت]. الساقُ تحمل `at` «هسّة» عمداً.
co() { echo "select (retail_checkout($CART242, jsonb_build_object('client_ref','$1','sale_at',$2,'sale_tz','${3:-Asia/Baghdad}','final_total',2000,'amount_paid',1500,'customer_name','زبون أمس','payment_details',jsonb_build_array(jsonb_build_object('method','cash','amount',1500,'at',now()))))).id::text"; }
Q() { psql -h $SOCK -p $PORT -U postgres -d $DB -tAc "$1" | tr -d '[:space:]'; }
TODAY_BG="(now() at time zone 'Asia/Baghdad')::date"

# ١) من يقدر
chk "الاستقبالُ بلا مفتاح المدير لا يؤرّخ (backdate_not_allowed)" \
    "$(fgc "$RCP" "$(co r242-rcp "$(dayAt 1)")")" "backdate_not_allowed"
chk "  ولا المصوّر" \
    "$(fgc "$PHO" "$(co r242-pho "$(dayAt 1)")")" "backdate_not_allowed"
$P -c "update _dvtest_flags set admin = true; insert into platform_sessions(admin_id, acting_clinic) values ('$ADM','$C1') on conflict do nothing;" >/dev/null
chk "  ولا مشغّلُ المنصّة داخل العيادة (سطرُ مالٍ يسمّي كادرَها — كـ0241)" \
    "$(fgc "$ADM" "$(co r242-adm "$(dayAt 1)")")" "backdate_operator_not_allowed"
$P -c "update _dvtest_flags set admin = false; delete from platform_sessions;" >/dev/null
chk "  والرفضُ لم يكتب فاتورةً ولم يمسّ الرصيد" \
    "select count(*)::text||'|'||(select stock::int from products where id='${BD}01')::text from invoices where client_ref like 'r242-%'" "0|10"

# ٢) صاحبُ العيادة: بيعةُ أمس الساعة ٣ العصر
ID1=$(Q "select _fgv('$C1', \$q\$$(co r242-1 "$(dayAt 1)")\$q\$)")
chk "صاحبُ العيادة يسجّل فاتورةَ أمس: يومُها أمس بساعتها، وختمُ الإدخال الآن" \
    "select ((created_at at time zone 'Asia/Baghdad')::date = $TODAY_BG - 1)::text||'|'||to_char(created_at at time zone 'Asia/Baghdad','HH24:MI')||'|'||(recorded_at > created_at and recorded_at > now() - interval '5 minutes')::text from invoices where id='$ID1'" "true|15:00|true"
chk "  والبندُ بتاريخ فاتورته (0133) لا بيوم الإدخال" \
    "select count(*) filter (where ii.created_at = i.created_at)::text||'/'||count(*)::text from invoice_items ii join invoices i on i.id = ii.invoice_id where i.id='$ID1'" "1/1"
chk "  والساقُ بلا \`at\` — فتُؤرَّخ بالفاتورة لا بـ«هسّة»" \
    "select count(*)::text||'|'||bool_and(not (l ? 'at'))::text from invoices i, jsonb_array_elements(i.payment_details) l where i.id='$ID1'" "1|true"
chk "  والمقبوضاتُ: ١٥٠٠ أمس، وصفرٌ بصندوق اليوم" \
    "select coalesce(sum(r.amount) filter (where (r.at at time zone 'Asia/Baghdad')::date = $TODAY_BG - 1), 0)::int::text||'|'||count(*) filter (where (r.at at time zone 'Asia/Baghdad')::date = $TODAY_BG)::text from (select set_config('request.jwt.claim.sub','$C1',true)) s, receipt_legs() r where r.invoice_id='$ID1'" "1500|0"
chk "  والدينُ ٥٠٠ والمخزونُ نزل ٢ (من الرصيد الحاليّ)" \
    "select (total - amount_paid)::int::text||'|'||(select stock::int from products where id='${BD}01')::text from invoices where id='$ID1'" "500|8"
chk "  والإعادةُ بنفس المرجع ترجع نفسَ الفاتورة بلا خصمٍ ثانٍ" \
    "select (_fgv('$C1', \$q\$$(co r242-1 "$(dayAt 1)")\$q\$) = '$ID1')::text||'|'||(select stock::int from products where id='${BD}01')::text" "true|8"
# «كما ثبتت» = ختمُ الفاتورة نفسُه قبل الإعادة وبعدها — لا «أقدمُ من ١٢ ساعة»: «أمس ١٥:٠٠ ببغداد» أقربُ من ذلك بين منتصف الليل والثالثة
# فجراً ببغداد، فكان الفحصُ يسقط بتلك الساعات وحدها والفاتورةُ سليمة (مقيس: ٠١:٠٩ ببغداد).
STAMP242=$(Q "select extract(epoch from created_at)::text from invoices where id='$ID1'")
chk "  **وإعادتُها بلا تاريخ (مسودّةٌ فقدته) ترجعها كما ثبتت — لا بيعةَ ثانيةً باليوم**" \
    "select (_fgv('$C1', \$q\$$(co r242-1 null)\$q\$) = '$ID1')::text||'|'||((select extract(epoch from created_at)::text from invoices where id='$ID1') = '$STAMP242' and '$STAMP242' <> '')::text" "true|true"
# كلُّ جزءٍ يقول نفسَه إن غاب: كان NULL واحدٌ (sold_at غائب) يمحو السطرَ كلَّه فيرجع الفحصُ «» لا يُعرف ما الناقص.
chk "  وسطرُ التدقيق يسمّيها «بيعة بيومٍ سابق» ويحمل يومَها" \
    "select coalesce((select coalesce(audit_kind(entity, action, details), 'no-kind')||'|'||coalesce(((details->>'sold_at')::timestamptz = (select created_at from invoices where id='$ID1'))::text, 'no-sold_at')||'|'||(details ? 'recorded_at')::text from audit_log where entity='invoices' and action='INSERT' and entity_id='$ID1' limit 1), 'no-audit-row')" "sale_backdated|true|true"
# والبابُ الذي تقرأ منه صفحةُ «سجل الحركات» نفسُه (activity_page: النوعُ من audit_kind والمختصرُ من activity_brief) —
# لا السطرُ الخامّ وحده: صفحةٌ لا ترى النوعَ أو اليومَ ميزةٌ غيرُ موجودة ولو كان السطرُ صحيحاً.
chk "  وصفحةُ «سجل الحركات» تقرؤها «بيع بيوم سابق» بيومها (activity_page)" \
    "select _pf('$C1', 'select coalesce((select kind||''|''||coalesce(((brief->>''sold_at'')::timestamptz = (select created_at from invoices where id = ''$ID1''))::text, ''no-sold_at'') from activity_page(now() - interval ''1 hour'', now() + interval ''1 hour'', array[''sale_backdated'']) where entity_id = ''$ID1'' limit 1), ''no-row'')')" "sale_backdated|true"
chk "  وحركةُ المادة تُسمّى «بيع» برقم الفاتورة — لا «تعديل» مجهول" \
    "select kind||':'||delta::int::text||':'||(ref_id = '$ID1')::text from (select set_config('request.jwt.claim.sub','$C1',true)) s, product_movements('${BD}01') order by at desc limit 1" "sale:-2:true"

# ٣) أيُّ يوم
chk "اليومُ نفسُه ليس تاريخاً سابقاً (sale_day_not_past)" \
    "$(fgc "$C1" "$(co r242-today "now()")")" "sale_day_not_past"
chk "  ولا الغد" \
    "$(fgc "$C1" "$(co r242-fut "now() + interval '1 day'")")" "sale_day_not_past"
chk "  وقبل ٧ أيام يُقبل" \
    "$(fgc "$C1" "$(co r242-7 "$(dayAt 7)")")" "ok"
chk "  وقبل ٨ أيام يُرفض (backdate_window)" \
    "$(fgc "$C1" "$(co r242-8 "$(dayAt 8)")")" "backdate_window"
chk "  ونصٌّ لا يُفهم تاريخاً يُرفض (sale_at_invalid)" \
    "$(fgc "$C1" "$(co r242-bad "'أمس'")")" "sale_at_invalid"
chk "  وتوقيتٌ مجهول يسقط لبغداد — لا رفضٌ لبيعةٍ صحيحة بسبب جهاز" \
    "$(fgc "$C1" "$(co r242-tz "$(dayAt 1)" "Mars/Olympus")")" "ok"
$P -c "insert into staff_elevations(user_id, clinic_id, until) values ('$RCP','$C1', now() + interval '30 minutes')
       on conflict (user_id) do update set until = excluded.until;" >/dev/null
chk "  والاستقبالُ بمفتاح المدير الحيّ يؤرّخ" \
    "$(fgc "$RCP" "$(co r242-pin "$(dayAt 2)")")" "ok"
$P -c "delete from staff_elevations;" >/dev/null

# ٤) بلا تاريخ: كما كان حرفاً
ID0=$(Q "select _fgv('$C1', \$q\$$(co r242-now null)\$q\$)")
chk "بيعةُ الآن بلا ختم إدخال وبتسميتها «بيع» — وساقُها كما أُرسلت" \
    "select (recorded_at is null and created_at > now() - interval '5 minutes')::text||'|'||(select audit_kind(entity, action, details) from audit_log where entity='invoices' and action='INSERT' and entity_id='$ID0')||'|'||(payment_details->0 ? 'at')::text from invoices where id='$ID0'" "true|sale|true"

# ٥) البابُ الجانبيّ مقفول — بدور authenticated فعلاً (_rls_try)
chk "الاستقبالُ لا ينقل بيعةَ اليوم لأمس بتحديثٍ مباشر (invoice_date_frozen)" \
    "select split_part(_rls_try('$RCP', 'update invoices set created_at = created_at - interval ''1 day'' where id = ''$ID0'''), ':', 3)" "invoice_date_frozen"
chk "  ولا المديرُ نفسُه (التأريخُ بشرطه من البيعة وحدها)" \
    "select split_part(_rls_try('$C1', 'update invoices set created_at = created_at - interval ''1 day'' where id = ''$ID0'''), ':', 3)" "invoice_date_frozen"
chk "  ولا ختمُ الإدخال يُمسح عن مؤرَّخة" \
    "select split_part(_rls_try('$C1', 'update invoices set recorded_at = null where id = ''$ID1'''), ':', 3)" "invoice_date_frozen"
chk "  ولا إدراجٌ مباشرٌ بتاريخٍ سابق" \
    "select split_part(_rls_try('$C1', 'insert into invoices (clinic_id, created_at) values (''$C1'', now() - interval ''3 days'')'), ':', 3)" "invoice_date_frozen"
chk "  والحارسُ لا يشدّ أكثر: الاسمُ يُعدَّل، والإدراجُ بلا تاريخ يمرّ" \
    "select _rls_try('$RCP', 'update invoices set customer_name = ''اسم مصحّح'' where id = ''$ID0''')||'|'||_rls_try('$C1', 'insert into invoices (clinic_id, notes) values (''$C1'', ''r242-direct'')')" "rows:1|rows:1"
chk "  والبيعةُ definer بمسار، والحارسُ invoker بمسار، ومحفّزُه على الإدراج والتحديث" \
    "select (select (prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text from pg_proc where proname='retail_checkout')||'|'||(select (not prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text from pg_proc where proname='invoices_guard_dates')||'|'||(select (tgtype & 4 = 4 and tgtype & 16 = 16)::text from pg_trigger where tgname='invoices_dates_guard')" "true|true|true"

# ── 0243: باركوداتُ المنتج بتشكيلة المتجر للمصوّر ─────────────────────────────
$P -c "delete from invoice_items where invoice_id in (select id from invoices where client_ref like 'r242-%' or notes = 'r242-direct');
       delete from invoices where client_ref like 'r242-%' or notes = 'r242-direct';" >/dev/null

# ── 0243: باركوداتُ المنتج بتشكيلة المتجر للمصوّر ─────────────────────────────
echo "▸ 0243: المصوّرُ يرى الرموزَ الإضافية كما يرى الأساسيّ — بلا توسيع"
PB=b2430000-0000-4000-8000-0000000000
$P -c "insert into products(id, clinic_id, name, barcode, stock, purchase_price, sell_price, alt_codes) values
         ('${PB}01','$C1','برموزٍ إضافية','243001', 3, 500, 1000, array['6281000000001','w90']),
         ('${PB}02','$C1','بلا رموز إضافية','243002', 3, 500, 1000, '{}') on conflict do nothing;" >/dev/null
chk "photo_products تعطي المصوّرَ الرموزَ الإضافية مع الأساسيّ" \
    "select _pf('$PHO', 'select (e->>''barcode'')||''|''||(e->''alt_codes'')::text from jsonb_array_elements(photo_products()) e where e->>''id'' = ''${PB}01''')" "243001|[\"6281000000001\",\"w90\"]"
chk "  ومنتجٌ بلا إضافيّة: قائمةٌ فارغة لا null" \
    "select _pf('$PHO', 'select (e->''alt_codes'')::text from jsonb_array_elements(photo_products()) e where e->>''id'' = ''${PB}02''')" "[]"
# قرارُ المالك (١٧/١٠): الباركودات نعم، والسعرُ لا — لا شراءً ولا بيعاً. أوّلُ تشغيلٍ بـCI قاس أنّ 0228 كانت تعطيه
# سعرَ البيع بقالب manageStore (والإنتاجُ قراءةً كذلك)؛ فـ0243 تحجبه عنه وحده. والمديرُ يراه كما كان.
chk "  ولا سعرَ شراءٍ ولا سعرَ بيعٍ للمصوّر — كما كان" \
    "select _pf('$PHO', 'select (not (e ? ''purchase_price'') and e->>''sell_price'' is null)::text from jsonb_array_elements(photo_products()) e where e->>''id'' = ''${PB}01''')" "true"
chk "    ولو حمل قالبُه manageStore (الحجبُ للمصوّر بعينه، لا لفقد الإذن)" \
    "select _pf('$PHO', 'select staff_can(''manageStore'')::text')" "true"
chk "  ومفاتيحُه مفاتيحُ 0228 + alt_codes وحدها — لا مفتاحَ جديد بلا قرار (سعرُ الشراء أو غيره يُفشلها)" \
    "select _pf('$PHO', 'select string_agg(k, '','' order by k collate \"C\") from jsonb_array_elements(photo_products()) e, jsonb_object_keys(e) k where e->>''id'' = ''${PB}01''')" \
    "alt_codes,barcode,category,company_id,company_name,expiry_date,id,image_path,name,pooled,sell_price,stock,store_desc,store_featured,store_visible,subcategory"
chk "  والمديرُ يراها كذلك (صفُّه الكامل يحملها أصلاً — والمتجرُ يتّفق للاثنين)" \
    "select _pf('$C1', 'select (e->''alt_codes'')::text from jsonb_array_elements(photo_products()) e where e->>''id'' = ''${PB}01''')" "[\"6281000000001\",\"w90\"]"
chk "  والمديرُ يرى سعرَ البيع كما كان — الحجبُ للمصوّر وحده" \
    "select _pf('$C1', 'select (e->>''sell_price'')::numeric::int::text from jsonb_array_elements(photo_products()) e where e->>''id'' = ''${PB}01''')" "1000"
chk "  والسياجُ كاملٌ بعدها" \
    "select coalesce(string_agg(t, ','), '') from verify_photographer_fence() t" ""

# ── 0244: المشغّلُ لا يظهر «متصلاً» بكادر عيادةٍ دخلها ─────────────────────────
# _rls_try بدور authenticated لا superuser: النبضةُ definer، لكنّ الفحصَ يجري كما يجري بالإنتاج.
echo "▸ 0244: حضورُ المشغّل لا يُكتب بعيادة زبون"
$P -c "delete from platform_sessions; delete from staff_presence where user_id='$ADM';
       update _dvtest_flags set admin = true;
       select platform_enter('$C1'::uuid) from (select set_config('request.jwt.claim.sub','$ADM',true)) s;" >/dev/null
# النبضةُ والعدُّ بجملتين: بجملةٍ واحدة يقرأ العدُّ لقطةَ أوّلها فلا يرى ما كتبته النبضة (صفرٌ كاذب).
chk "المشغّلُ داخلُ ١١١١ ينبض بلا خطأ" "select _rls_try('$ADM', 'select presence_beat(''المشغّل'')')" "rows:1"
chk "  ولا صفَّ حضورٍ باسمه عندها ولا بغيرها" "select count(*)::text from staff_presence where user_id='$ADM'" "0"
chk "  والكادرُ الحقيقيّ ينبض بعيادته كما كان" "select _rls_try('$RCP', 'select presence_beat(''استقبال'')')" "rows:1"
chk "    فصفُّه يُرى (والعدُّ نفسُه يرى ما يُكتب — صفرُ المشغّل ليس عمى)" \
    "select count(*)::text from staff_presence where user_id='$RCP'" "1"
$P -c "select platform_leave() from (select set_config('request.jwt.claim.sub','$ADM',true)) s;" >/dev/null
chk "  وخارجَ أيّ عيادة ينبض" "select _rls_try('$ADM', 'select presence_beat(''المشغّل'')')" "rows:1"
chk "    بعيادته هو" "select string_agg(clinic_id::text, ',') from staff_presence where user_id='$ADM'" "$ADM"
# صفٌّ قديم (قبل 0244) بعيادةٍ دخلها، وصفٌّ بعيادةٍ لم يدخلها قطّ — الإعادةُ تمسح الأوّلَ وحده.
$P -c "insert into staff_presence (clinic_id, user_id, name, role) values ('$C1','$ADM','قديم','manager'), ('$C3','$ADM','لم يدخلها','manager') on conflict do nothing;" >/dev/null
$P -f "$MIG/0244_presence_not_operator.sql" >/dev/null
chk "  الإعادةُ تمسح صفَّه بعيادةٍ دخلها، وتُبقي عيادتَه وما لم يدخله" \
    "select string_agg(k, ',' order by k) from (select case clinic_id when '$ADM' then 'own' when '$C1' then 'C1' when '$C3' then 'C3' end k from staff_presence where user_id='$ADM') x" "C3,own"
$P -f "$MIG/0244_presence_not_operator.sql" >/dev/null
chk "  وإعادةٌ ثانية بلا أثر" \
    "select count(*)::text from staff_presence where user_id='$ADM'" "2"
chk "  والنبضةُ definer بمسار" \
    "select (prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text from pg_proc where proname='presence_beat'" "true"
$P -c "delete from staff_presence where user_id='$ADM'; delete from platform_sessions; update _dvtest_flags set admin = false;" >/dev/null

# ── 0245: فحصُ المخزن — القاعدةُ والمرآة صفّاً بصفّ، والدورُ والعزلُ والبوّابة ─────────
# القالبُ (audit-fixture.mjs) عيادتان بكلّ نوعٍ وسببٍ وحدّ (عمرُ ٣٠ يوماً بالضبط، بيعٌ قبل ٣٠ بالضبط،
# صافٍ سالب، فاتورةٌ مردودة، حوضُ قسم، مادةُ حقل)، والمتوقَّعُ تحسبه inventoryAudit من المصدر بأربع
# نوافذ — ورابعتُها تنتهي قبل «الآن» فبيعُ ما بعدها لا يُحسب. والعيادةُ الثانية تحمل ما لو تسرّب لغيّر
# ناتجَ الأولى (نفسُ البادئة بشركةٍ أخرى، نفسُ الاسم، الرمزُ الداخليّ بمولّدها، فاتورتُها تبيع مادةَ الأولى).
echo "▸ 0245: فحصُ المخزن — القاعدة والمرآة"
AU1=a2450000-0000-4000-8000-0000000000a1
AU2=a2450000-0000-4000-8000-0000000000a2
AUF=$(mktemp -d)
node "$HERE/../../scripts/audit-fixture.mjs" "$AUF" >/dev/null
$P -f "$AUF/fixture.sql" >/dev/null
$P -f "$AUF/calls.sql" >/dev/null
psql -h $SOCK -p $PORT -U postgres -d $DB -tAc "select json_object_agg(id, res) from _audit_out" > "$AUF/out.json"
if node "$HERE/../../scripts/audit-parity.mjs" "$AUF" | sed 's/^/ /'; then :; else fail=1; fi
chk "inv_code_kind = codeKind على كلّ رمزٍ ملغوم (عربيّ، إكسل، شرقيّ، خفيّ، خارج BMP)" \
    "select count(*)::text from _audit_codes where inv_code_kind(raw) is distinct from expected" "0"
chk "  والقالبُ يقيس شيئاً: ٦٠ رمزاً فأكثر بكلّ الأشكال العشرة" \
    "select (count(*) >= 60 and count(distinct expected) = 10)::text from _audit_codes" "true"
chk "inv_gtin_ok = gtinOk" \
    "select count(*)::text from _audit_gtin where inv_gtin_ok(v) is distinct from ok" "0"
chk "الدالّة definer بمسارٍ مثبَّت، stable، وتحصر عيادتَها بنصّها" \
    "select (prosecdef and proconfig @> array['search_path=public'] and provolatile = 's' and prosrc like '%clinic_id = v_clinic%')::text
       from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'report_inventory_audit'" "true"
chk "  ولا تُنادى بلا هويّة، وتبقى للمسجَّلين" \
    "select (not has_function_privilege('anon','public.report_inventory_audit(timestamptz,timestamptz)','execute')
             and has_function_privilege('authenticated','public.report_inventory_audit(timestamptz,timestamptz)','execute'))::text" "true"
chk "  والمساعدتان immutable بمسار" \
    "select count(*)::text from pg_proc where proname in ('inv_code_kind','inv_gtin_ok') and provolatile = 'i' and coalesce(array_to_string(proconfig,','),'') like '%search_path%'" "2"
# النداءُ الذي تناديه الواجهة (مصفوفةٌ واحدة): invoker فوق الدالّة الحارسة، ولا anon — والقالبُ
# كلُّه (audit-parity أعلاه) مرّ منها، فهنا يكفي أن يساوي عددُها عددَ الجدول.
chk "report_inventory_audit_json: invoker بمسار، ولا تُنادى بلا هويّة" \
    "select (not prosecdef and proconfig @> array['search_path=public']
             and not has_function_privilege('anon','public.report_inventory_audit_json(int)','execute')
             and to_regprocedure('public.report_inventory_audit_json(timestamptz,timestamptz)') is null)::text
       from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'report_inventory_audit_json'" "true"
# والنافذةُ بساعة الخادم: الغلافُ يأخذ الأيامَ وحدها. يساوي التجميعَ نفسَه (الذي مرّ منه القالبُ أعلاه)
# على now()-p_days×24h..now() حرفاً — now() واحدةٌ بالمعاملة — ولا صفَّ يضيع.
chk "  وهي التجميعُ نفسُه على آخر ٩٠ يوماً بساعة الخادم، حرفاً" \
    "select (r = (select coalesce(jsonb_agg(to_jsonb(x) order by x.kind, x.product_id), '[]'::jsonb)
                  from report_inventory_audit(now() - make_interval(hours => 2160), now()) x)
             and jsonb_array_length(r) > 0)::text
       from (select set_config('request.jwt.claim.sub','$AU1',true)) s, lateral (select report_inventory_audit_json(90) as r) j" "true"
chk "  والمدى يُفحص تحتها: ٦ و٤٠١ وnull تُرفض بـ22023، و٧ تمرّ" \
    "select split_part(_rls_try('$C1', 'select report_inventory_audit_json(6)'), ':', 2)||'|'||split_part(_rls_try('$C1', 'select report_inventory_audit_json(401)'), ':', 2)||'|'||split_part(_rls_try('$C1', 'select report_inventory_audit_json(null)'), ':', 2)||'|'||left(_rls_try('$C1', 'select report_inventory_audit_json(7)'), 5)" \
    "22023|22023|22023|rows:"
AQ="select 1 from report_inventory_audit(now() - interval ''90 days'', now())"
# بدور authenticated فعلاً (الحزمةُ superuser لا ترى صنفَ الصلاحيات) — والرفضُ 42501 لا خطأٌ آخر.
chk "بدور authenticated: المديرُ والطبيبُ يقرآنه، والاستقبالُ والمصوّرُ يُرفضان" \
    "select left(_rls_try('$C1', '$AQ'), 5)||'|'||left(_rls_try('$VET', '$AQ'), 5)||'|'||split_part(_rls_try('$RCP', '$AQ'), ':', 2)||'|'||split_part(_rls_try('$PHO', '$AQ'), ':', 2)" \
    "rows:|rows:|42501|42501"
$P -c "insert into staff_elevations(user_id, clinic_id, until) values ('$PHO','$C1', now() + interval '10 minutes')
         on conflict (user_id) do update set until = excluded.until, clinic_id = excluded.clinic_id;" >/dev/null
chk "  والمصوّرُ المرفوعُ بـPIN المدير ما زال مرفوضاً (الدورُ الأساس)" \
    "select _pf('$PHO', 'select auth_role()')||'|'||split_part(_rls_try('$PHO', '$AQ'), ':', 2)" "manager|42501"
$P -c "delete from staff_elevations where user_id = '$PHO';" >/dev/null
chk "  والبوّابةُ ترفضها للمصوّر قبلها (ليست بقائمته)، ولا تمسّ المدير" \
    "select split_part(_gate('$PHO', '/rpc/report_inventory_audit'), ':', 3)||'|'||_gate('$C1', '/rpc/report_inventory_audit')" "photographer_forbidden|rows:1"
chk "عيادةٌ أخرى لا ترى موادَّ الأولى" \
    "select count(*)::text from (select set_config('request.jwt.claim.sub','$AU2',true)) s cross join lateral report_inventory_audit(now() - interval '90 days', now()) h where h.product_id::text like 'a2450000-b000-%'" "0"
chk "  وتلقى موادَّها هي" \
    "select (count(*) > 0)::text from (select set_config('request.jwt.claim.sub','$AU2',true)) s cross join lateral report_inventory_audit(now() - interval '90 days', now()) h where h.product_id::text like 'a2450000-b002-%'" "true"
W90F=$(node -e "console.log(JSON.parse(require('fs').readFileSync('$AUF/expected.json','utf8')).calls.w90.from)")
W90T=$(node -e "console.log(JSON.parse(require('fs').readFileSync('$AUF/expected.json','utf8')).calls.w90.to)")
$P -f "$MIG/0245_inventory_audit.sql" >/dev/null
chk "  والإعادةُ بلا أثر: نفسُ الناتج حرفاً" \
    "select (_audit_call('$AU1', '$W90F', '$W90T')::text = (select res::text from _audit_out where id = 'w90'))::text" "true"
chk "  ولا تكتب شيئاً: لا جدولَ تغيّر بالنداءات" \
    "select (select count(*) from products where clinic_id = '$AU1')::text||'|'||(select count(*) from invoices where clinic_id = '$AU1')::text" \
    "$(node -e "const e=JSON.parse(require('fs').readFileSync('$AUF/expected.json','utf8'));console.log(e.counts.products+'|'+e.counts.invoices)")"
$P -c "drop table if exists _audit_codes, _audit_gtin, _audit_out; drop function if exists _audit_call(uuid, timestamptz, timestamptz);" >/dev/null
rm -rf "$AUF"

# ── 0247: حقلُ المشغّل — مساحةُ دواجن له، مفصولةٌ عن عيادته، بنفس طريق الدخول ─────
# الحارسُ (غيرُ المشغّل يُرفض ولا يُنشأ شيء)، والإنشاءُ مرّةً (حسابٌ واحد مهما تكرّر الدخول)،
# والباقةُ «حقل» تُثبَّت بكلّ دخول، وعيادتُه وباقتُها لا تُمسّان، والكتابةُ بدور authenticated
# تهبط بالحقل، وحسابُ المساحة بشكل GoTrue (لا null بحقلٍ نصّيّ) وبملفٍّ لا يظهر بدليل العيادات —
# والملفُّ يكتبه محفّزُ handle_new_user كما بالإنتاج (منسوخٌ بأعمدة القالب: الدورُ هنا text).
echo "▸ 0247: حقلُ المشغّل"
$P -c "delete from platform_sessions; update _dvtest_flags set admin = false;
       insert into subscriptions (clinic_id, plan, period, current_period_end, was_subscriber)
         values ('$ADM', 'super', 'annual', now() + interval '300 days', true)
         on conflict (clinic_id) do update set plan = 'super', period = 'annual',
           current_period_end = now() + interval '300 days', was_subscriber = true;
       create or replace function _t247_new_user() returns trigger language plpgsql security definer set search_path = public as \$fn\$
       declare meta_role text := coalesce(new.raw_user_meta_data->>'role', 'owner');
               acct text := case when meta_role = 'owner' then 'owner' else 'clinic' end;
       begin
         insert into public.profiles (id, full_name, role, phone, roles)
         values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email,'@',1)), meta_role,
                 nullif(new.raw_user_meta_data->>'phone',''), array[acct])
         on conflict (id) do nothing;
         return new;
       end \$fn\$;
       drop trigger if exists _t247_on_auth_user_created on auth.users;
       create trigger _t247_on_auth_user_created after insert on auth.users for each row execute function _t247_new_user();" >/dev/null
chk "غيرُ المشغّل لا يدخل حقلاً" \
    "select left(_pf_try('$ADM', 'select platform_farm_enter()::text'), 7) || '|' || left(_pf_try('$ADM', 'select platform_workspace_ids()::text'), 7)" "guarded|guarded"
chk "  ولا يُنشأ له حسابٌ ولا مساحة" \
    "select (select count(*) from platform_workspaces)::text || '|' || (select count(*) from auth.users where email like '%@workspace.doctorvet.invalid')::text" "0|0"
$P -c "update _dvtest_flags set admin = true;" >/dev/null
chk "المشغّلُ يدخل حقله — أوّلَ مرّةٍ يُنشأ" \
    "select _pf('$ADM', 'select (platform_farm_enter()->>''created'')')" "true"
WS=$(psql -h $SOCK -p $PORT -U postgres -d $DB -tAc "select clinic_id from platform_workspaces where admin_id='$ADM' and kind='farm'" | tr -d '[:space:]')
chk "  مساحةٌ ثانية لا عيادتُه ولا عيادةُ زبون" \
    "select ('$WS' <> '' and '$WS' not in ('$ADM','$C1','$C2'))::text" "true"
chk "  فتصير عيادتُه الحقلَ وبدور مدير" \
    "select (_pf('$ADM', 'select auth_clinic()::text') = '$WS')::text || '|' || _pf('$ADM', 'select auth_role()')" "true|manager"
chk "  والسياقُ والمعرّفُ يقولانها" \
    "select (_pf('$ADM', 'select platform_context()->>''acting''') = '$WS' and _pf('$ADM', 'select platform_workspace_ids()->>''mine''') = '$WS' and _pf('$ADM', 'select (platform_workspace_ids()->''all'') ? ''$WS''') = 'true')::text" "true"
chk "  وباقتُها «حقل» سنويةٌ حتى ٢٠٩٩ — لا تجربةَ تنقضي" \
    "select plan || '/' || period || '/' || was_subscriber::text || '/' || (current_period_end = '2099-12-31 00:00:00+03')::text from subscriptions where clinic_id='$WS'" "farm/annual/true/true"
chk "  وباقةُ عيادته لم تُمسّ" \
    "select plan || '/' || (current_period_end > now() + interval '200 days')::text from subscriptions where clinic_id='$ADM'" "super/true"
chk "  واسمُها «حقلي»، وبسجلّ الجلسات الداخلي سببُها" \
    "select (select clinic_name from clinic_prefs where clinic_id='$WS') || '|' || (select count(*) from platform_session_log where admin_id='$ADM' and acting_clinic='$WS' and left_at is null and reason='حقلي (الدواجن)')::text" "حقلي|1"
chk "حسابُ المساحة بشكل GoTrue: لا null بحقلٍ نصّيّ، بلا كلمة سرّ، محظورٌ، وبريدُه لا يُسلَّم" \
    "select (aud = 'authenticated' and role = 'authenticated' and instance_id = '00000000-0000-0000-0000-000000000000'
             and encrypted_password = '' and confirmation_token = '' and recovery_token = '' and email_change_token_new = ''
             and email_change = '' and email_change_token_current = '' and reauthentication_token = '' and phone_change = ''
             and phone_change_token = '' and not is_sso_user and not is_anonymous and banned_until > now() + interval '900 years'
             and email like 'farm-%@workspace.doctorvet.invalid' and raw_app_meta_data->>'doctorvet_workspace' = 'farm')::text
       from auth.users where id='$WS'" "true"
chk "  وملفُّه (من المحفّز) owner لا clinic — فلا يظهر بدليل العيادات العامّ (0078)" \
    "select (select role || ':' || array_to_string(roles, ',') from profiles where id='$WS') || '|' || (select count(*) from profiles where id='$WS' and ('clinic' = any(coalesce(roles, '{}'::text[])) or role = 'admin'))::text" "owner:owner|0"
# الكتابةُ بدور authenticated فعلاً (الحزمةُ superuser تتجاوز RLS): حقلٌ يُضاف داخل المساحة يهبط بها.
chk "داخلَ الحقل: حقلٌ يُضاف بدور authenticated" \
    "select _rls_try('$ADM', 'insert into poultry_farms (name) values (''حقلُ المشغّل'')')" "rows:1"
chk "  فيهبط بالمساحة لا بعيادته" \
    "select (select count(*) from poultry_farms where name='حقلُ المشغّل' and clinic_id='$WS')::text || '|' || (select count(*) from poultry_farms where name='حقلُ المشغّل' and clinic_id <> '$WS')::text" "1|0"
$P -c "update clinic_prefs set clinic_name = 'حقل التجربة' where clinic_id='$WS';
       update subscriptions set plan = 'super', period = 'monthly', current_period_end = now() - interval '1 day' where clinic_id='$WS';" >/dev/null
chk "الدخولُ الثاني لا يُنشئ شيئاً" \
    "select _pf('$ADM', 'select (platform_farm_enter()->>''created'')') || '|' || (select count(*) from platform_workspaces)::text || '|' || (select count(*) from auth.users where email like '%@workspace.doctorvet.invalid')::text" "false|1|1"
chk "  ويعيد الباقةَ «حقلاً» لو أُلغيت من لوحة الاشتراكات" \
    "select plan || '/' || period || '/' || (current_period_end = '2099-12-31 00:00:00+03')::text from subscriptions where clinic_id='$WS'" "farm/annual/true"
chk "  ولا يدهس اسماً سمّاه المشغّل" "select clinic_name from clinic_prefs where clinic_id='$WS'" "حقلالتجربة"
chk "  وسجلُّ الجلسات: الأولى مقفلة والثانية مفتوحة" \
    "select count(*) filter (where left_at is not null)::text || '/' || count(*) filter (where left_at is null)::text from platform_session_log where admin_id='$ADM' and acting_clinic='$WS'" "1/1"
chk "النبضُ يراها كعيادة — فالواجهةُ تعزلها بـplatform_workspace_ids" \
    "select count(*)::text from platform_pulse() where clinic_id='$WS'" "1"
chk "الانتقالُ من الحقل لعيادة زبون بنفس الطريق" \
    "select (_pf('$ADM', 'select (platform_enter(''$C1'')->>''clinic_id'')') = '$C1' and _pf('$ADM', 'select auth_clinic()::text') = '$C1')::text" "true"
chk "والخروجُ يعيده لعيادته، وباقتُها كما كانت" \
    "select _pf('$ADM', 'select (platform_leave()->>''was_acting'')') || '|' || (_pf('$ADM', 'select auth_clinic()::text') = '$ADM')::text || '|' || (select plan from subscriptions where clinic_id='$ADM')" "true|true|super"
chk "الدالّتان definer بمسارٍ مثبَّت، وممنوعتان على anon" \
    "select count(*) filter (where prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%')::text || '|' || count(*) filter (where has_function_privilege('anon', p.oid, 'execute'))::text
       from pg_proc p where proname in ('platform_farm_enter','platform_workspace_ids')" "2|0"
chk "  والبوّابةُ ترفضها للمصوّر (ليست بقائمته)" \
    "select split_part(_gate('$PHO', '/rpc/platform_farm_enter'), ':', 3)" "photographer_forbidden"
chk "والجدولُ محميٌّ بلا سياسة، وحجبُه موثَّق" \
    "select ((select relrowsecurity from pg_class where relname='platform_workspaces') and (select count(*) from pg_policies where tablename='platform_workspaces') = 0
             and not exists (select 1 from verify_rls_coverage() v where v.\"الجدول\" = 'platform_workspaces'))::text" "true"
$P -f "$MIG/0247_operator_farm_workspace.sql" >/dev/null
chk "  والإعادةُ بلا أثر: مساحةٌ واحدة وحسابٌ واحد" \
    "select (select count(*) from platform_workspaces)::text || '|' || (select count(*) from auth.users where email like '%@workspace.doctorvet.invalid')::text" "1|1"
$P -c "drop trigger if exists _t247_on_auth_user_created on auth.users; drop function if exists _t247_new_user();
       delete from platform_sessions; update _dvtest_flags set admin = false;" >/dev/null

echo "▸ 0248: صاحبُ الحيوان يسجّل برقم هاتفه"
# القالبُ يحمل ما يحمله الإنتاج: عمودُ الهاتف بـauth.users، ونوعُ الدور، وقيدا 0001 على
# البريد والاسم (not null) — بلاهما يمرّ الصفُّ هنا ويسقط هناك («Database error saving new user»).
# القيدان `not valid`: صفوفُ القالب القديمة بلا بريد لا تُفحص، والجديدةُ تُفحص كالإنتاج.
$P -c "alter table auth.users add column if not exists phone text;
       alter table profiles add column if not exists city text;
       do \$d\$ begin create type user_role as enum ('owner','doctor','reception','admin'); exception when duplicate_object then null; end \$d\$;
       alter table profiles drop constraint if exists _t248_nn;
       alter table profiles add constraint _t248_nn check (email is not null and full_name is not null) not valid;
       drop trigger if exists _t248_on_auth_user_created on auth.users;
       create trigger _t248_on_auth_user_created after insert on auth.users for each row execute function handle_new_user();
       insert into auth.users (id, email, phone, raw_user_meta_data) values
         ('24800000-0000-0000-0000-000000000001', null, '9647701112222', '{\"role\":\"owner\",\"phone\":\"+9647701112222\"}'),
         ('24800000-0000-0000-0000-000000000002', null, '9647703334444', '{\"role\":\"owner\",\"full_name\":\"أبو علي\",\"phone\":\"+9647703334444\"}'),
         ('24800000-0000-0000-0000-000000000003', 'clinic248@test.vet', null, '{\"role\":\"admin\",\"full_name\":\"عيادة الرحمة\",\"city\":\"الرياض\",\"country\":\"SA\"}'),
         ('24800000-0000-0000-0000-000000000004', 'noname248@test.vet', null, '{\"role\":\"owner\",\"full_name\":\"  \"}'),
         ('24800000-0000-0000-0000-000000000005', null, '9647705556666', '{}');" >/dev/null
chk "هاتفٌ بلا بريدٍ ولا اسم: الحسابُ ينشأ، والبريدُ فارغٌ لا null والاسمُ رقمُه" \
    "select email || '|' || full_name || '|' || phone || '|' || role::text || '|' || array_to_string(roles, ',') from profiles where id = '24800000-0000-0000-0000-000000000001'" \
    "|+9647701112222|+9647701112222|owner|owner"
chk "  والاسمُ المكتوب يبقى اسمَه" \
    "select full_name || '|' || phone from profiles where id = '24800000-0000-0000-0000-000000000002'" "أبوعلي|+9647703334444"
chk "تسجيلُ العيادة بالبريد كما كان حرفاً بحرف" \
    "select full_name || '|' || email || '|' || role::text || '|' || array_to_string(roles, ',') || '|' || city from profiles where id = '24800000-0000-0000-0000-000000000003'" \
    "عيادةالرحمة|clinic248@test.vet|admin|clinic|الرياض"
chk "اسمٌ من فراغاتٍ لا يُحفظ فراغاً — يأخذ اسمَ البريد" \
    "select full_name from profiles where id = '24800000-0000-0000-0000-000000000004'" "noname248"
chk "بلا بياناتٍ أصلاً: رقمُ الدخول اسماً وهاتفاً" \
    "select full_name || '|' || phone from profiles where id = '24800000-0000-0000-0000-000000000005'" "9647705556666|9647705556666"
# (الامتيازُ يبقى من PUBLIC الافتراضيّ كما بالإنتاج منذ 0039 — والمحفّزُ دالّةُ trigger لا تُنادى عبر
#  الواجهة أصلاً. الفحصُ يقول ما تضمنه الهجرةُ وحدها.)
chk "المحفّزُ definer بمسارٍ مثبَّت، ودالّةُ trigger لا تُنادى عبر الواجهة" \
    "select (p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') like '%search_path%')::text || '|' || (p.prorettype = 'trigger'::regtype)::text from pg_proc p where p.proname = 'handle_new_user'" \
    "true|true"
$P -f "$MIG/0248_phone_signup_profile.sql" >/dev/null
chk "  والإعادةُ بلا أثر" "select count(*)::text from profiles where id::text like '24800000-%'" "5"
$P -c "drop trigger if exists _t248_on_auth_user_created on auth.users;
       alter table profiles drop constraint if exists _t248_nn;
       delete from profiles where id::text like '24800000-%';
       delete from auth.users where id::text like '24800000-%';" >/dev/null

# ── 0249: صاحبُ الحيوان يقرأ سجلَّ العيادة ولا يكتبه، ويطالب برقمٍ أكّده الخادم ──────
# كلُّ ما يخصّ المالكَ هنا بـ`_rls_try` (دور authenticated فعلاً): الحزمةُ superuser تتجاوز
# RLS، فـ«المالكُ لا يكتب» بلاه يمرّ قبل الهجرة وبعدها. والقالبُ بأسماء الإنتاج وسياساته:
# حلقةُ 0001 على الخمسة كلّها، وقارئةُ 0004 وكاتبتُها، و`profiles_self_delete` (0049).
echo "▸ 0249: المالكُ يقرأ ولا يكتب، والمطالبةُ برقمٍ مؤكَّد"
C1=11111111-1111-1111-1111-111111111111
OF=f2490000-0000-4000-8000-0000000000f1   # كتب رقمَ زبونٍ بملفّه — لم يُثبته
OU=f2490000-0000-4000-8000-0000000000f2   # رقمُ الدخول نفسُه بلا تأكيد
OR=f2490000-0000-4000-8000-0000000000f3   # صاحبُ الرقم: أكّدته GoTrue
OS=f2490000-0000-4000-8000-0000000000f4   # ربطٌ قديمٌ قبل 0249 (حيوانُ زبونٍ آخر)
PA=f2490000-0000-4000-8000-0000000000a1; PB=f2490000-0000-4000-8000-0000000000a2; PS=f2490000-0000-4000-8000-0000000000a3
R=f2490000-0000-4000-8000-0000000000
$P -c "insert into auth.users(id, phone, phone_confirmed_at) values
         ('$OF', null, null), ('$OU', '9647701112233', null), ('$OR', '9647701112233', now()), ('$OS', null, null)
       on conflict (id) do update set phone = excluded.phone, phone_confirmed_at = excluded.phone_confirmed_at;
       insert into profiles(id, role, roles, phone) values
         ('$OF','owner','{owner}','0770 111 2233'), ('$OU','owner','{owner}',null),
         ('$OR','owner','{owner}',null), ('$OS','owner','{owner}',null)
       on conflict (id) do update set role = excluded.role, roles = excluded.roles, phone = excluded.phone;
       -- حيوانا عيادةٍ سجّلتهما برقم الزبون (صفُّ المراجع: صاحبُه حسابُ العيادة، كما بالإنتاج)،
       -- وثالثٌ رُبط بحساب مالكٍ قبل اليوم ورقمُه رقمُ زبونٍ آخر.
       insert into pets(id, name, clinic_id, owner_id, owner_phone) values
         ('$PA','بسبوسة','$C1','$C1','0770 111 2233'), ('$PB','ريكس','$C1','$C1','+964 770 111 2233'),
         ('$PS','لولو','$C1','$OS','07709998877')
       on conflict (id) do nothing;
       insert into vaccinations(id, pet_id, name, clinic_id, notes) values ('${R}01','$PA','سعار','$C1','العيادة') on conflict do nothing;
       insert into medical_visits(id, pet_id, clinic_id) values ('${R}02','$PA','$C1') on conflict do nothing;
       insert into treatment_entries(id, pet_id, medication, time, amount, clinic_id) values ('${R}03','$PA','سيفترياكسون','08:00','1ml','$C1') on conflict do nothing;
       insert into weight_logs(id, pet_id, weight_kg, clinic_id) values ('${R}04','$PA',4.2,'$C1') on conflict do nothing;
       insert into media_items(id, pet_id, kind, url, clinic_id) values ('${R}05','$PA','xray','$PA/x.png','$C1') on conflict do nothing;" >/dev/null

chk "الخمسة: سياسةُ المالك قراءةٌ وحدها (<t>_owner = SELECT)" \
    "select string_agg(tablename || ':' || cmd, ',' order by tablename) from pg_policies
      where schemaname='public' and policyname = tablename || '_owner'
        and tablename in ('weight_logs','vaccinations','media_items','medical_visits','treatment_entries')" \
    "media_items:SELECT,medical_visits:SELECT,treatment_entries:SELECT,vaccinations:SELECT,weight_logs:SELECT"
chk "  ولا متساهلةَ كتابةٍ بملكيّة الحيوان باقية (verify_owner_read_only)" \
    "select count(*)::text from verify_owner_read_only()" "0"
chk "  وكلُّ ما أُسقط مدوَّنٌ بنصّه وسببه — سبعٌ بالقالب" \
    "select count(*)::text || '|' || count(*) filter (where qual is not null or with_check is not null)::text from rls_policy_superseded where migration='0249'" "7|7"
chk "  وبرهانُ 0128 يستثني المدوَّن وحده: لا ضاع شيءٌ ولا تبدّل" \
    "select (ضاعت + تغير_شرطها + تغيرت_صلاحياتها)::text || '|' || (سياسات_انفحصت > 0)::text from verify_rls_equivalence()" "0|true"
chk "  والسياجُ قائمٌ على كلّ أمر" \
    "select coalesce(string_agg(t, ','), '') from verify_photographer_fence() t" ""

# (أ) رقمٌ بالملفّ الشخصيّ لا يربط شيئاً — ولا تعديلُه بعد التسجيل
chk "(أ) ملفٌّ برقم الزبون بلا تأكيد: يطالب فيربط صفراً" \
    "select _rls_try('$OF', 'select 1 from claim_pets_by_phone()')" "rows:0"
chk "  ويبدّل رقمَه بملفّه (مسموح) ثم يطالب: صفرٌ أيضاً" \
    "select _rls_try('$OF', 'update profiles set phone=''07701112233'' where id=''$OF''') || '|' || _rls_try('$OF', 'select 1 from claim_pets_by_phone()')" "rows:1|rows:0"
chk "  ورقمُ الدخول نفسُه قبل تأكيده: صفر" \
    "select _rls_try('$OU', 'select 1 from claim_pets_by_phone()')" "rows:0"
chk "  والحيوانان باقيان بحساب العيادة" \
    "select count(*)::text from pets where id in ('$PA','$PB') and owner_id='$C1'" "2"

# (ب) الرقمُ المؤكَّد يطالب كما كان — بكلّ صيغ كتابة الرقم
chk "(ب) رقمٌ أكّدته GoTrue: يربط حيوانَي رقمه" \
    "select _rls_try('$OR', 'select 1 from claim_pets_by_phone(''أم علي'')')" "rows:2"
chk "  مربوطان به، واسمُ المراجع الذي كتبته العيادة لا يُمسّ إلا فارغاً" \
    "select count(*)::text || '|' || min(owner_name) from pets where id in ('$PA','$PB') and owner_id='$OR'" "2|أمعلي"
chk "  والمطالبةُ الثانية لا تربط شيئاً جديداً" \
    "select _rls_try('$OR', 'select 1 from claim_pets_by_phone()')" "rows:0"
chk "  والدالّةُ definer بمسارٍ مثبَّت، تقرأ تأكيدَ GoTrue ولا تقرأ هاتفَ الملفّ" \
    "select (prosecdef and coalesce(array_to_string(proconfig,','),'') like '%search_path%'
             and prosrc like '%phone_confirmed_at%' and prosrc not like '%pr.phone%')::text
       from pg_proc where proname='claim_pets_by_phone'" "true"

# (ج) المالكُ لا يعدّل ولا يحذف سجلَّ العيادة — لا مباشرةً ولا بالتسلسل
