        '((clinic_id = auth_clinic()) AND ((auth_role() = ''manager''::text) OR (amount_paid = ( SELECT i.amount_paid FROM invoices i WHERE (i.id = invoices.id)))))'),
       ('0128','public','profiles','profiles_self_update','PERMISSIVE','{public}','UPDATE','(id = auth.uid())',
