    "select ضاعت::text || '|' || تغير_شرطها::text || '|' || تغيرت_صلاحياتها::text from verify_rls_equivalence()" "2|2|0"
$P -f "$MIG/0251_record_old_policy_rewrites.sql" >/dev/null
