OVSAME='[{"product_id":"'${R}04'","qty":1,"unit":"sub"},{"product_id":"'${R}03'","qty":"1","unit":"sub"},{"product_id":"'${R}02'","qty":2,"unit":"sub"},{"product_id":"'${R}01'","qty":10.000,"unit":"sub"}]'
