         ('${A253}31','$C1','شراء يقطع',0,100,200,false,null,null,null),
         ('${A253}32','$C1','شراء يشال',0,100,200,false,null,null,null),
         ('${A253}33','$C1','بديل الشراء',0,100,200,false,null,null,null),
