  if $P -tA -f "$USDP/run.sql" >"$USDP/actual.txt" 2>"$USDP/run.err"; then :; else tail -3 "$USDP/run.err"; echo "   ✗ نداءُ تطابق الدولار ما رجع"; fail=1; fi
  if node "$HERE/usd-parity.mjs" check "$USDP"; then :; else fail=1; fi
